/// Looks up an authentic SVG logo string by its service/brand identifier.
/// Returns null when no vector SVG is mapped for the ID.
String? resolveBrandSvg(String iconId) {
  final normalized = iconId.trim().toLowerCase();
  final target = _brandSvgAliases[normalized] ?? normalized;
  return _brandSvgs[target];
}
